Functions & Error — Kitchen Recipe with Failure Alarm

Kategori: Go  Minggu 3: Fungsi & Error Handling

Learning Objectives

— Go must return error
Pattern  — alarm if divide by 0
to close door after done,  for bulk
Difference  vs  in functions

--Why This Matters (Non-IT)

Recipe  if no error check → negative stock, loss. Go forces you check  each divide, open file, API — safe for non-IT fearing forget.

--Program: Safe Kitchen Functions

go
package main
import ("errors"; "fmt")

func divide(a, b float64) (float64, error) {
	if b == 0 {
		return 0, errors.New("cannot divide by 0 — check stock")
	}
	return a / b, nil
}

func calc(a, b int) (sum int, prod int) {
	sum = a b
	prod = a b
	return
}

func average(nums ...float64) float64 {
	total := 0.0
	for _, n := range nums {
		total += n
	}
	if len(nums) == 0 {
		return 0
	}
	return total / float64(len(nums))
}

func main() {
	defer fmt.Println("Done — defer runs last")
	result, err := divide(10, 2)
	if err != nil {
		fmt.Println("Error:", err)
	} else {
		fmt.Printf("10/2 = %.1f\n", result)
	}
	_, err = divide(5, 0)
	if err != nil {
		fmt.Println("Divide 0 error:", err)
	}
	j, k := calc(4, 5)
	fmt.Printf("Sum %d, Prod %d\n", j, k)
	fmt.Printf("Average: %.1f\n", average(80, 90, 75))
}
