// produk.entity.ts — cetak biru (bukan tabel SQL manual!)
import { Entity, PrimaryGeneratedColumn, Column } from 'typeorm';

@Entity('produks')
export class Produk {
  @PrimaryGeneratedColumn()
  id: number;

  @Column({ length: 100 })
