    // println!("{}", s1); // ❌ error: value borrowed after move
    println!("s2: {}", s2);

    // Pinjam baca &s
    let s = String::from("Bu Siti");
    let len = hitung_panjang(&s); // pinjam, s tetap
    println!("'{}' panjang {}", s, len);

    // Pinjam tulis &mut
    let mut t = String::from("Beras");
    tambah_gula(&mut t);
