struct Keranjang<T> {
  items: Vec<T>,
}

impl<T> Keranjang<T> {
  fn new() -> Self { Self { items: Vec::new() } }
  fn tambah(&mut self, item: T) { self.items.push(item); }
  fn pertama(&self) -> Option<&T> { self.items.first() }
}

fn main() {
  let mut ks = Keranjang { items: vec!["Beras", "Gula"] };
  ks.tambah("Kopi");
  println!("Pertama: {:?}", ks.pertama());

