// Observer — langganan (TechPulse)
class Toko {
  private pelanggan: ((nama:string)=>void)[] = [];
  langganan(fn: (nama:string)=>void){ this.pelanggan.push(fn); }
  stokHabis(nama: string){ this.pelanggan.forEach(fn=>fn(nama)); }
}
